"""
make_web_L8.py -- writes lectures/L8/web_en.md and web_ro.md (the text of the web lecture, format of
lectures/common/build_web_lecture.py), with every number read from L8_numbers.json and the frame hashes read from the
decks, then builds web/L8.html, web/L8_ro.html and web/L8_log.txt.
Run after build_L8.py:  python3 lectures/L8/make_web_L8.py
"""
import json
import os
import re
import subprocess
import sys
import unicodedata

HERE = os.path.dirname(os.path.abspath(__file__))
COMMON = os.path.join(HERE, "..", "common")
sys.path.insert(0, COMMON)
import build_web_lecture as bw  # noqa: E402

K = 8
N = json.load(open(os.path.join(HERE, f"L{K}_numbers.json")))


def get(key):
    v = N
    for p in key.split("."):
        v = v[p]
    return v


MON = {"en": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
       "ro": ["ianuarie", "februarie", "martie", "aprilie", "mai", "iunie", "iulie", "august", "septembrie", "octombrie",
              "noiembrie", "decembrie"]}


def fmt(x, spec, lang):
    if isinstance(x, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", x):
        return f"{int(x[8:10])} {MON[lang][int(x[5:7]) - 1]} {x[:4]}"
    s = format(x, spec)
    if lang == "ro":
        s = s.replace(",", " ").replace(".", ",")
    if s.startswith("-"):
        s = "−" + s[1:]
    return s


class Page:
    def __init__(self, lang):
        self.lang = lang
        self.out = []
        self.deck = bw.read_deck(K, lang)

    def v(self, key, spec=""):
        return fmt(get(key), spec, self.lang)

    def h(self, title_start):
        """Hash of the first frame whose (plain) title starts with title_start."""
        key = re.sub(r"[^a-z0-9]", "", unicodedata.normalize("NFKD", title_start).lower())
        for f in self.deck["frames"]:
            t = re.sub(r"[^a-z0-9]", "", unicodedata.normalize("NFKD", f["title"]).lower())
            if t.startswith(key):
                return f["hash"]
        raise KeyError(f"no frame starting with: {title_start}")

    def add(self, s):
        self.out.append(s.strip("\n") + "\n")

    def block(self, title, frame=None, text=""):
        hh = f" {{h={self.h(frame or title)}}}" if (frame or title) else ""
        self.add(f"## {title}{hh}\n\n{text.strip()}\n")

    def write(self):
        with open(os.path.join(HERE, f"web_{self.lang}.md"), "w", encoding="utf-8") as fh:
            fh.write("\n".join(self.out))


def page(lang):
    P = Page(lang)
    v = P.v
    en = lang == "en"
    T = (lambda a, b: a if en else b)
    P.add(f"<!--\nWeb version of Lecture {K} ({lang.upper()}). Generated by lectures/L{K}/make_web_L{K}.py from L{K}_numbers.json and the deck;"
          f" built into web/L{K}{'' if en else '_ro'}.html by lectures/common/build_web_lecture.py.\n-->\n")
    # ------------------------------------------------------------------ intro
    P.add("## @intro\n")
    P.add(T(
        "A classifier answers a narrow question: given this transaction, is it fraud? A generative model answers a wider one: what do transactions, "
        "images, daily returns or yield curves look like, and what else could they look like? Once a model has learnt the distribution of the data, "
        "it can flag observations that do not fit, simulate scenarios for stress tests, produce synthetic data that can be shared without client "
        "records, and compress many series into a few interpretable factors.",
        "Un clasificator răspunde la o întrebare îngustă: este această tranzacție o fraudă? Un model generativ răspunde la una mai largă: cum arată "
        "tranzacțiile, imaginile, randamentele zilnice sau curbele randamentelor și cum ar mai putea arăta? Odată ce a învățat distribuția datelor, "
        "modelul poate semnala observațiile care nu se potrivesc, poate simula scenarii pentru teste de stres, poate produce date sintetice care se pot "
        "partaja fără înregistrări despre clienți și poate comprima multe serii în cîțiva factori interpretabili."))
    P.add(T(
        "This lecture builds the four main families of deep generative models, the autoencoder (AE), the variational autoencoder (VAE), the generative "
        "adversarial network (GAN) and the denoising diffusion probabilistic model (DDPM), and tests each of them on real data against a classical "
        "benchmark: card fraud from the ULB Machine Learning Group, clothing images from Fashion-MNIST, daily returns of the S&P 500 and the daily "
        "AAA yield curve of the euro area published by the European Central Bank.",
        "Cursul construiește cele patru familii principale de modele generative profunde, autoencoderul (AE), autoencoderul variațional (VAE), "
        "rețeaua generativă adversarială (GAN) și modelul probabilistic de difuzie cu eliminarea zgomotului (DDPM), și testează fiecare familie pe date "
        "reale, alături de un model clasic de referință: fraudele cu carduri de la ULB Machine Learning Group, imaginile de îmbrăcăminte Fashion-MNIST, "
        "randamentele zilnice ale indicelui S&P 500 și curba zilnică a randamentelor AAA din zona euro, publicată de Banca Centrală Europeană."))
    P.add("@goals")
    P.add(T(
        "- **Explain** the difference between a discriminative model $p(y\\mid\\mathbf x)$ and a generative model $p(\\mathbf x)$, and why finance needs both.\n"
        "- **Derive and train** an autoencoder, a VAE, a GAN and a diffusion model.\n"
        "- **Use** them for fraud detection, image generation, synthetic returns and yield-curve scenarios, each against a benchmark.\n"
        "- **Judge** synthetic data by tails, volatility clustering, Value-at-Risk (VaR) backtests and the regimes they reproduce.\n",
        "- **Explicați** diferența dintre un model discriminativ $p(y\\mid\\mathbf x)$ și un model generativ $p(\\mathbf x)$ și de ce finanțele au nevoie de amîndouă.\n"
        "- **Derivați și antrenați** un autoencoder, un VAE, un GAN și un model de difuzie.\n"
        "- **Folosiți-le** pentru detectarea fraudei, generarea de imagini, randamente sintetice și scenarii ale curbei randamentelor, fiecare comparat cu un model de referință.\n"
        "- **Judecați** datele sintetice după cozi, gruparea volatilității, testele retrospective ale valorii la risc (VaR) și regimurile pe care le reproduc.\n"))

    # ------------------------------------------------------------------ 1
    P.add(T("# Why generative models\n\nA generative model learns the whole distribution of the data, not only the boundary between classes.",
            "# De ce modele generative\n\nUn model generativ învață întreaga distribuție a datelor, nu doar granița dintre clase."))
    P.block(T("A generative model learns how the data themselves arise", "Un model generativ învață cum apar datele"), text=T(
        f"""A discriminative model estimates $p(y\\mid\\mathbf x)$, the probability of a label given the inputs. A generative model estimates $p(\\mathbf x)$, or the joint $p(\\mathbf x,y)=p(\\mathbf x\\mid y)p(y)$, and is usually fitted by maximum likelihood,

$$ \\hat{{\\boldsymbol\\theta}}=\\arg\\max_{{\\boldsymbol\\theta}}\\sum_{{i=1}}^{{n}}\\log p_{{\\boldsymbol\\theta}}(\\mathbf x_i). $$ {{#eq:ml}}

Knowing $p(\\mathbf x)$ gives four uses in finance: a low density marks a suspicious observation (anomaly detection); draws from the model are scenarios for stress tests and risk measures; synthetic samples can be shared without client records; and a latent representation compresses many correlated series into a few factors.

@practice a classifier ranks clients, a generative model also shows what could happen.""",
        f"""Un model discriminativ estimează $p(y\\mid\\mathbf x)$, probabilitatea unei etichete dat fiind inputul. Un model generativ estimează $p(\\mathbf x)$ sau distribuția comună $p(\\mathbf x,y)=p(\\mathbf x\\mid y)p(y)$ și se estimează de obicei prin verosimilitate maximă,

$$ \\hat{{\\boldsymbol\\theta}}=\\arg\\max_{{\\boldsymbol\\theta}}\\sum_{{i=1}}^{{n}}\\log p_{{\\boldsymbol\\theta}}(\\mathbf x_i). $$ {{#eq:ml}}

Cunoașterea lui $p(\\mathbf x)$ aduce patru utilizări în finanțe: o densitate mică marchează o observație suspectă (detectarea anomaliilor); extragerile din model sînt scenarii pentru teste de stres și măsuri de risc; eșantioanele sintetice se pot partaja fără înregistrări despre clienți; iar o reprezentare latentă comprimă multe serii corelate în cîțiva factori.

@practice un clasificator ordonează clienții, un model generativ arată și ce s-ar putea întîmpla."""))
    P.block(T("Latent-variable models", "Modele cu variabile latente"), text=T(
        """Eleven yields or 784 pixels are driven by a handful of hidden factors. A latent-variable model writes $p(\\mathbf x)=\\int p(\\mathbf x\\mid\\mathbf z)p(\\mathbf z)\\,d\\mathbf z$ with $\\mathbf z\\in\\mathbb R^k$, $k$ much smaller than the dimension of the data. In the linear-Gaussian case, $\\mathbf x=W\\mathbf z+\\boldsymbol\\mu+\\boldsymbol\\varepsilon$, this is probabilistic principal component analysis (PCA), whose likelihood has a closed form. With a neural decoder the integral has no closed form, and each family of this lecture pays for the flexibility differently: the VAE maximises a lower bound, the GAN gives up the likelihood, and diffusion builds a bound step by step.""",
        """Unsprezece randamente sau 784 de pixeli sînt determinate de cîțiva factori ascunși. Un model cu variabile latente scrie $p(\\mathbf x)=\\int p(\\mathbf x\\mid\\mathbf z)p(\\mathbf z)\\,d\\mathbf z$, cu $\\mathbf z\\in\\mathbb R^k$ și $k$ mult mai mic decît dimensiunea datelor. În cazul liniar-gaussian, $\\mathbf x=W\\mathbf z+\\boldsymbol\\mu+\\boldsymbol\\varepsilon$, se obține analiza probabilistă a componentelor principale (PCA), cu verosimilitate în formă închisă. Cu un decodor neuronal integrala nu mai are formă închisă, iar fiecare familie din acest curs plătește altfel pentru flexibilitate: VAE maximizează o margine inferioară, GAN renunță la verosimilitate, iar difuzia construiește o margine pas cu pas."""))
    P.block(T("Four families of generative models", "Patru familii de modele generative"), text=T(
        """| Family | Training signal | Likelihood | Sampling |
|---|---|---|---|
| AE | reconstruction error | none | not a generator |
| VAE | evidence lower bound | lower bound | one pass, blurry |
| GAN | game against a discriminator | none | one pass, sharp |
| DDPM | denoising error | lower bound | many steps, faithful |

Likelihood, sample quality and speed rarely come together; normalising flows, with an exact likelihood, complete the picture.""",
        """| Familia | Ce se optimizează | Verosimilitate | Generarea |
|---|---|---|---|
| AE | eroarea de reconstrucție | nu | nu este generator |
| VAE | marginea inferioară a verosimilității | margine inferioară | o trecere, imagini neclare |
| GAN | joc contra unui discriminator | nu | o trecere, imagini clare |
| DDPM | eroarea de eliminare a zgomotului | margine inferioară | mulți pași, fidel |

Verosimilitatea, calitatea eșantioanelor și viteza rareori vin împreună; fluxurile de normalizare, cu verosimilitate exactă, completează tabloul."""))
    P.add("## @end\n\n" + T("Generative models learn $p(\\mathbf x)$; the families differ in how they handle the intractable likelihood.",
                             "Modelele generative învață $p(\\mathbf x)$; familiile diferă prin felul în care tratează verosimilitatea greu de calculat.") + "\n")

    # ------------------------------------------------------------------ 2 AE
    P.add(T("# Autoencoders: anomaly detection for card fraud\n\nAn autoencoder trained on normal transactions flags those it cannot rebuild.",
            "# Autoencodere: detectarea anomaliilor la fraude cu carduri\n\nUn autoencoder antrenat pe tranzacții normale le semnalează pe cele pe care nu le poate reconstrui."))
    P.block(T("An autoencoder squeezes the data through a bottleneck and rebuilds them", "Un autoencoder comprimă datele printr-un strat îngust și le reconstruiește"), text=T(
        f"""An encoder $f_\\phi$ maps the input to a code $\\mathbf z\\in\\mathbb R^k$ and a decoder $g_\\psi$ maps it back; both are small multilayer perceptrons (MLP) with rectified linear units (ReLU). Training minimises the reconstruction error, and the same error is the anomaly score:

$$ \\min_{{\\phi,\\psi}}\\frac1n\\sum_{{i=1}}^n\\big\\|\\mathbf x_i-g_\\psi(f_\\phi(\\mathbf x_i))\\big\\|^2,\\qquad s(\\mathbf x)=\\tfrac1d\\|\\mathbf x-\\hat{{\\mathbf x}}\\|^2. $$ {{#eq:ae}}

With linear $f$ and $g$ the optimum spans the same subspace as PCA with $k$ components, so PCA is the natural benchmark. Our autoencoder has {v('fraud.d_in')} inputs (the 28 anonymised components and the log amount), a bottleneck of 8 and {v('ae.params', ',')} parameters, and is trained on legitimate transactions only.""",
        f"""Un codificator $f_\\phi$ duce inputul într-un cod $\\mathbf z\\in\\mathbb R^k$, iar un decodor $g_\\psi$ îl aduce înapoi; ambele sînt perceptroni multistrat (MLP) mici, cu unități liniare rectificate (ReLU). Antrenarea minimizează eroarea de reconstrucție, iar aceeași eroare este scorul de anomalie:

$$ \\min_{{\\phi,\\psi}}\\frac1n\\sum_{{i=1}}^n\\big\\|\\mathbf x_i-g_\\psi(f_\\phi(\\mathbf x_i))\\big\\|^2,\\qquad s(\\mathbf x)=\\tfrac1d\\|\\mathbf x-\\hat{{\\mathbf x}}\\|^2. $$ {{#eq:ae}}

Cu $f$ și $g$ liniare, optimul generează același subspațiu ca PCA cu $k$ componente, deci PCA este modelul de referință firesc. Autoencoderul nostru are {v('fraud.d_in')} de intrări (cele 28 de componente anonimizate și logaritmul sumei), un strat îngust de 8 și {v('ae.params', ',')} de parametri și este antrenat numai pe tranzacții legitime."""))
    P.block(T("The fraud experiment: two days of card payments, split in time", "Experimentul de fraudă: două zile de plăți cu cardul, împărțite în timp"), text=T(
        f"""The data are the credit-card transactions of European cardholders released by the ULB Machine Learning Group and Worldline (Dal Pozzolo et al., 2015). Our file keeps all {v('fraud.n_fraud')} frauds and 10 % of the legitimate transactions, {v('fraud.n_rows', ',')} rows, with weights that restore the full data. The first 60 % of the time span is the training part (legitimate transactions only, {v('fraud.n_train_legit', ',')} rows), the next 20 % the validation part for early stopping, and the last 20 % the test part: {v('fraud.n_full_test', ',')} transactions of the full data with {v('fraud.n_test_fraud')} frauds ({v('fraud.test_fraud_rate_pct', '.3f')} %). The metrics are the area under the precision-recall curve (PR-AUC) and the area under the receiver operating characteristic curve (ROC-AUC), weighted to the full data.""",
        f"""Datele sînt tranzacțiile cu carduri ale unor deținători europeni, publicate de ULB Machine Learning Group și Worldline (Dal Pozzolo et al., 2015). Fișierul nostru păstrează toate cele {v('fraud.n_fraud')} de fraude și 10 % dintre tranzacțiile legitime, {v('fraud.n_rows', ',')} de rînduri, cu ponderi care refac datele complete. Primele 60 % din interval sînt partea de antrenare (numai tranzacții legitime, {v('fraud.n_train_legit', ',')} de rînduri), următoarele 20 % partea de validare pentru oprirea timpurie, iar ultimele 20 % partea de test: {v('fraud.n_full_test', ',')} de tranzacții din datele complete, cu {v('fraud.n_test_fraud')} de fraude ({v('fraud.test_fraud_rate_pct', '.3f')} %). Măsurile sînt aria de sub curba precizie-recall (PR-AUC) și aria de sub curba caracteristicii de operare a receptorului (ROC-AUC), ponderate la datele complete."""))
    P.block(T("Frauds are hard to rebuild: their reconstruction error is far larger", "Fraudele sînt greu de reconstruit: eroarea lor de reconstrucție este mult mai mare"), text=T(
        f"""On the test part the median reconstruction error of a fraud is {v('ae.median_ratio', '.1f')} times that of a legitimate transaction. The two distributions still overlap: many frauds look normal to a model that only knows normal behaviour.

@chart ae_error_dist
Reconstruction error of the autoencoder on the test part, legitimate transactions (weighted) and frauds.""",
        f"""Pe partea de test, eroarea mediană de reconstrucție a unei fraude este de {v('ae.median_ratio', '.1f')} ori mai mare decît a unei tranzacții legitime. Cele două distribuții se suprapun totuși: multe fraude par normale unui model care cunoaște doar comportamentul normal.

@chart ae_error_dist
Eroarea de reconstrucție a autoencoderului pe partea de test, tranzacții legitime (ponderate) și fraude."""))
    P.block(T("Without labels the autoencoder finds frauds; with labels a simple classifier finds many more",
              "Fără etichete, autoencoderul găsește fraude; cu etichete, un clasificator simplu găsește mult mai multe"), text=T(
        f"""The PR-AUC on the test part is {v('ae.ap', '.1f')} % for the autoencoder (standard deviation {v('ae.ap_sd', '.1f')} over 3 seeds), {v('ae.ap_pca', '.1f')} % for PCA and {v('ae.ap_logit', '.1f')} % for a logistic regression that uses the labels; a random score would give {v('ae.base_ap', '.3f')} %. The ROC-AUC is high for all three ({v('ae.auc', '.1f')}, {v('ae.auc_pca', '.1f')} and {v('ae.auc_logit', '.1f')} %): with one fraud in several hundred transactions it hides the differences that the PR-AUC shows.

@chart ae_pr
Precision-recall curves on the test part, weighted to the full data.""",
        f"""PR-AUC pe partea de test este {v('ae.ap', '.1f')} % pentru autoencoder (abatere standard {v('ae.ap_sd', '.1f')} pe 3 semințe), {v('ae.ap_pca', '.1f')} % pentru PCA și {v('ae.ap_logit', '.1f')} % pentru o regresie logistică ce folosește etichetele; un scor aleator ar da {v('ae.base_ap', '.3f')} %. ROC-AUC este mare pentru toate trei ({v('ae.auc', '.1f')}, {v('ae.auc_pca', '.1f')} și {v('ae.auc_logit', '.1f')} %): la o fraudă la cîteva sute de tranzacții ascunde diferențele pe care le arată PR-AUC.

@chart ae_pr
Curbele precizie-recall pe partea de test, ponderate la datele complete."""))
    P.block(T("Bottleneck size and anomaly detection", "Dimensiunea stratului îngust și detectarea anomaliilor"), text=T(
        f"""With a bottleneck of 2 the PR-AUC is {get('ae.bottleneck')['2']:.1f} %, with 8 it is {get('ae.bottleneck')['8']:.1f} % and with 24 it is {get('ae.bottleneck')['24']:.1f} % (mean of 2 seeds); the best size is {v('ae.best_k')}. Too narrow, and even normal payments are rebuilt badly; too wide, and the network learns to copy frauds as well.

@chart ae_bottleneck
Test PR-AUC of the autoencoder by bottleneck size, with PCA as benchmark.

@practice choose $k$ on a validation period, never on the frauds you will report on.""",
        f"""Cu un strat îngust de 2, PR-AUC este {fmt(get('ae.bottleneck')['2'], '.1f', 'ro')} %, cu 8 este {fmt(get('ae.bottleneck')['8'], '.1f', 'ro')} %, iar cu 24 este {fmt(get('ae.bottleneck')['24'], '.1f', 'ro')} % (media pe 2 semințe); dimensiunea cea mai bună este {v('ae.best_k')}. Prea îngust, și chiar plățile normale sînt reconstruite prost; prea larg, și rețeaua învață să copieze și fraudele.

@chart ae_bottleneck
PR-AUC de test al autoencoderului după dimensiunea stratului îngust, cu PCA ca model de referință.

@practice alegeți $k$ pe o perioadă de validare, niciodată pe fraudele despre care veți raporta."""))
    P.block(T("What a fraud team gets from the top 0.1 % of scores", "Ce obține echipa antifraudă din primele 0,1 % scoruri"), text=T(
        f"""If the team reviews the 0.1 % highest scores of the test part, {v('ae.n_alerts_top01')} alerts, it finds {v('ae.top01_frauds_ae')} frauds with the autoencoder ({v('ae.top01_recall_ae', '.1f')} % of all test frauds), {v('ae.top01_frauds_pca')} with PCA and {v('ae.top01_frauds_logit')} with the logistic regression ({v('ae.top01_recall_logit', '.1f')} %). Labels are worth a lot: supervised learning wins whenever confirmed frauds exist. The autoencoder is the detector of the unknown, a complement and not a replacement.

@practice run both: the classifier for known fraud patterns, the autoencoder to surface new ones for investigators to label.""",
        f"""Dacă echipa verifică primele 0,1 % scoruri din partea de test, {v('ae.n_alerts_top01')} de alerte, găsește {v('ae.top01_frauds_ae')} fraude cu autoencoderul ({v('ae.top01_recall_ae', '.1f')} % din toate fraudele de test), {v('ae.top01_frauds_pca')} cu PCA și {v('ae.top01_frauds_logit')} cu regresia logistică ({v('ae.top01_recall_logit', '.1f')} %). Etichetele valorează mult: învățarea supervizată cîștigă ori de cîte ori există fraude confirmate. Autoencoderul este detectorul necunoscutului, un complement, nu un înlocuitor.

@practice folosiți-le pe amîndouă: clasificatorul pentru tiparele cunoscute, autoencoderul pentru a scoate la iveală tipare noi, pe care investigatorii le etichetează."""))
    P.add("## @end\n\n" + T("An autoencoder is a model of normal behaviour; without labels it finds part of the frauds, with labels a supervised model finds far more.",
                             "Un autoencoder este un model al comportamentului normal; fără etichete găsește o parte din fraude, cu etichete un model supervizat găsește mult mai multe.") + "\n")

    # ------------------------------------------------------------------ 3 VAE
    P.add(T("# Variational autoencoders\n\nThe VAE turns the autoencoder into a probabilistic generator by learning a distribution of codes.",
            "# Autoencodere variaționale\n\nVAE transformă autoencoderul într-un generator probabilist, învățînd o distribuție a codurilor."))
    P.block(T("The VAE makes the autoencoder a probabilistic generator", "VAE transformă autoencoderul într-un generator probabilist"), text=T(
        """The encoder outputs a Gaussian $q_\\phi(\\mathbf z\\mid\\mathbf x)=\\mathcal N(\\boldsymbol\\mu_\\phi(\\mathbf x),\\operatorname{diag}\\boldsymbol\\sigma_\\phi^2(\\mathbf x))$ and the decoder a likelihood $p_\\theta(\\mathbf x\\mid\\mathbf z)$. The log-likelihood is bounded from below by the evidence lower bound (ELBO):

$$ \\log p_\\theta(\\mathbf x)\\ge\\mathbb E_{q_\\phi(\\mathbf z\\mid\\mathbf x)}\\big[\\log p_\\theta(\\mathbf x\\mid\\mathbf z)\\big]-\\mathrm{KL}\\big(q_\\phi(\\mathbf z\\mid\\mathbf x)\\,\\|\\,p(\\mathbf z)\\big). $$ {#eq:elbo}

The first term rewards good reconstructions; the second, the Kullback–Leibler divergence (KL) from the prior $p(\\mathbf z)=\\mathcal N(0,I)$, packs all codes around the origin, so that a random code decodes to a realistic image. For Gaussians it has the closed form $\\tfrac12\\sum_j(\\mu_j^2+\\sigma_j^2-\\log\\sigma_j^2-1)$.""",
        """Codificatorul produce o gaussiană $q_\\phi(\\mathbf z\\mid\\mathbf x)=\\mathcal N(\\boldsymbol\\mu_\\phi(\\mathbf x),\\operatorname{diag}\\boldsymbol\\sigma_\\phi^2(\\mathbf x))$, iar decodorul o verosimilitate $p_\\theta(\\mathbf x\\mid\\mathbf z)$. Log-verosimilitatea este mărginită inferior de marginea inferioară a verosimilității (ELBO):

$$ \\log p_\\theta(\\mathbf x)\\ge\\mathbb E_{q_\\phi(\\mathbf z\\mid\\mathbf x)}\\big[\\log p_\\theta(\\mathbf x\\mid\\mathbf z)\\big]-\\mathrm{KL}\\big(q_\\phi(\\mathbf z\\mid\\mathbf x)\\,\\|\\,p(\\mathbf z)\\big). $$ {#eq:elbo}

Primul termen răsplătește reconstrucțiile bune; al doilea, divergența Kullback–Leibler (KL) față de distribuția a priori $p(\\mathbf z)=\\mathcal N(0,I)$, adună toate codurile în jurul originii, astfel încît un cod aleator să producă o imagine realistă. Pentru gaussiene are forma închisă $\\tfrac12\\sum_j(\\mu_j^2+\\sigma_j^2-\\log\\sigma_j^2-1)$."""))
    P.block(T("The reparameterisation trick", "Trucul reparametrizării"), text=T(
        f"""Sampling $\\mathbf z$ is not differentiable, but $\\mathbf z=\\boldsymbol\\mu_\\phi(\\mathbf x)+\\boldsymbol\\sigma_\\phi(\\mathbf x)\\odot\\boldsymbol\\varepsilon$ with $\\boldsymbol\\varepsilon\\sim\\mathcal N(0,I)$ is: the randomness sits in $\\boldsymbol\\varepsilon$, which does not depend on the parameters. Our VAE is trained on Fashion-MNIST, {v('vae.n_train', ',')} training and {v('vae.n_test', ',')} test grey images of 28 × 28 pixels showing 10 kinds of clothing, with a Bernoulli decoder; the network 784–400–200–$k$ has {v('vae.params_16', ',')} parameters for $k=16$ and is trained for {v('vae.epochs')} epochs.""",
        f"""Extragerea lui $\\mathbf z$ nu este derivabilă, dar $\\mathbf z=\\boldsymbol\\mu_\\phi(\\mathbf x)+\\boldsymbol\\sigma_\\phi(\\mathbf x)\\odot\\boldsymbol\\varepsilon$, cu $\\boldsymbol\\varepsilon\\sim\\mathcal N(0,I)$, este: hazardul stă în $\\boldsymbol\\varepsilon$, care nu depinde de parametri. VAE-ul nostru este antrenat pe Fashion-MNIST, {v('vae.n_train', ',')} de imagini de antrenare și {v('vae.n_test', ',')} de test, gri, de 28 × 28 de pixeli, cu 10 tipuri de îmbrăcăminte, și are un decodor Bernoulli; rețeaua 784–400–200–$k$ are {v('vae.params_16', ',')} de parametri pentru $k=16$ și este antrenată {v('vae.epochs')} de epoci."""))
    P.block(T("A two-dimensional latent space already sorts the products", "Un spațiu latent cu două dimensiuni sortează deja produsele"), text=T(
        f"""With only two latent dimensions and no labels, shoes, bags and garments fall into separate regions. A 15-nearest-neighbour classifier on the two latent means reaches {v('vae.knn_acc_2d', '.1f')} % accuracy (5-fold, test images): the VAE has learnt an organisation of the products without being told what they are.

@chart vae_latent
Latent means of the 10,000 test images, VAE with $k=2$, coloured by class.""",
        f"""Cu doar două dimensiuni latente și fără etichete, încălțămintea, gențile și hainele ajung în regiuni separate. Un clasificator cu 15 vecini pe cele două medii latente atinge o acuratețe de {v('vae.knn_acc_2d', '.1f')} % (5 partiții, imaginile de test): VAE a învățat o organizare a produselor fără să i se spună ce sînt.

@chart vae_latent
Mediile latente ale celor 10 000 de imagini de test, VAE cu $k=2$, colorate după clasă."""))
    P.block(T("Quality of VAE reconstructions and generated samples", "Calitatea reconstrucțiilor VAE și a eșantioanelor generate"), text=T(
        """The first row shows real test images, the second their reconstructions through a 16-dimensional code, the third new images decoded from random codes. The blur comes from the Gaussian posterior and the pixel-wise loss: the decoder averages over the plausible details.

@chart vae_samples
Real, reconstructed and generated images, VAE with $k=16$.""",
        """Primul rînd arată imagini reale de test, al doilea reconstrucția lor printr-un cod cu 16 dimensiuni, al treilea imagini noi, decodate din coduri aleatoare. Neclaritatea vine din distribuția a posteriori gaussiană și din pierderea calculată pixel cu pixel: decodorul face media detaliilor plauzibile.

@chart vae_samples
Imagini reale, reconstruite și generate, VAE cu $k=16$."""))
    P.block(T("Training trades reconstruction against the KL penalty", "Antrenarea negociază între reconstrucție și penalizarea KL"), text=T(
        f"""On the test images, after the last epoch, the reconstruction term is {v('vae.beta.b1.rec', '.1f')} nats per image and the KL term {v('vae.beta.b1.kl', '.1f')} nats, so the ELBO is {v('vae.elbo_16', '.1f')} nats. The KL rises while the error falls: the encoder spends more information on each image as it learns.

@chart vae_elbo
Reconstruction and KL terms of the ELBO on the test images, by epoch.""",
        f"""Pe imaginile de test, după ultima epocă, termenul de reconstrucție este {v('vae.beta.b1.rec', '.1f')} nats pe imagine, iar termenul KL {v('vae.beta.b1.kl', '.1f')} nats, deci ELBO este {v('vae.elbo_16', '.1f')} nats. KL crește cînd eroarea scade: codificatorul folosește mai multă informație pentru fiecare imagine pe măsură ce învață.

@chart vae_elbo
Termenii de reconstrucție și KL ai ELBO pe imaginile de test, pe epoci."""))
    P.block(T("β-VAE: reconstruction quality and latent-space structure", "β-VAE: calitatea reconstrucției și structura spațiului latent"),
            frame=T("beta-VAE: reconstruction quality", "beta-VAE: calitatea reconstrucției"), text=T(
        f"""Multiplying the KL term by $\\beta$ changes the balance. With $\\beta=0.5$ the reconstruction term is {v('vae.beta.b05.rec', '.1f')} nats and {v('vae.beta.b05.active')} of the 16 latent dimensions are active (KL above 0.05); with $\\beta=4$ the reconstruction worsens to {v('vae.beta.b4.rec', '.1f')} nats and only {v('vae.beta.b4.active')} dimensions stay active. A larger $\\beta$ gives smoother and more disentangled codes; a smaller one gives better copies and poorer samples.

@practice for scenario generation prefer a tidy latent space ($\\beta\\ge1$); for compression prefer reconstruction ($\\beta<1$).""",
        f"""Înmulțirea termenului KL cu $\\beta$ schimbă echilibrul. Cu $\\beta=0{{,}}5$, termenul de reconstrucție este {v('vae.beta.b05.rec', '.1f')} nats și {v('vae.beta.b05.active')} dintre cele 16 dimensiuni latente sînt active (KL peste 0,05); cu $\\beta=4$, reconstrucția se înrăutățește la {v('vae.beta.b4.rec', '.1f')} nats și rămîn active doar {v('vae.beta.b4.active')} dimensiuni. Un $\\beta$ mai mare dă coduri mai netede și mai separate; unul mai mic dă copii mai bune și eșantioane mai slabe.

@practice pentru generarea de scenarii preferați un spațiu latent ordonat ($\\beta\\ge1$); pentru comprimare, reconstrucția ($\\beta<1$)."""))
    P.add("## @end\n\n" + T("The VAE maximises the ELBO = reconstruction − KL; the reparameterisation trick makes it trainable and β sets the balance.",
                             "VAE maximizează ELBO = reconstrucție − KL; trucul reparametrizării îl face antrenabil, iar β stabilește echilibrul.") + "\n")

    # ------------------------------------------------------------------ 4 GAN
    P.add(T("# Generative adversarial networks\n\nA GAN learns to sample from the data distribution by playing against a discriminator.",
            "# Rețele generative adversariale\n\nUn GAN învață să extragă din distribuția datelor jucînd împotriva unui discriminator."))
    P.block(T("Generative adversarial networks: generator and discriminator", "Rețelele generative adversariale: generatorul și discriminatorul"), text=T(
        """The generator $G$ turns noise $\\mathbf z$ into fake data; the discriminator $D$ gives the probability that its input is real. They play

$$ \\min_G\\max_D\\ \\mathbb E_{\\mathbf x\\sim p_{data}}[\\log D(\\mathbf x)]+\\mathbb E_{\\mathbf z}[\\log(1-D(G(\\mathbf z)))]. $$ {#eq:gan}

For a fixed generator the best discriminator is $D^*(\\mathbf x)=p_{data}(\\mathbf x)/(p_{data}(\\mathbf x)+p_G(\\mathbf x))$, and the value of the game becomes $-\\log 4+2\\,\\mathrm{JS}(p_{data}\\|p_G)$, where the Jensen–Shannon divergence (JS) is zero only when the generator reproduces the data. At that point $D^*=1/2$ everywhere. A GAN never writes down a likelihood; it is judged by what its samples get right.""",
        """Generatorul $G$ transformă zgomotul $\\mathbf z$ în date false; discriminatorul $D$ dă probabilitatea ca inputul să fie real. Ei joacă

$$ \\min_G\\max_D\\ \\mathbb E_{\\mathbf x\\sim p_{data}}[\\log D(\\mathbf x)]+\\mathbb E_{\\mathbf z}[\\log(1-D(G(\\mathbf z)))]. $$ {#eq:gan}

Pentru un generator fixat, cel mai bun discriminator este $D^*(\\mathbf x)=p_{data}(\\mathbf x)/(p_{data}(\\mathbf x)+p_G(\\mathbf x))$, iar valoarea jocului devine $-\\log 4+2\\,\\mathrm{JS}(p_{data}\\|p_G)$, unde divergența Jensen–Shannon (JS) este nulă numai cînd generatorul reproduce datele. Atunci $D^*=1/2$ peste tot. Un GAN nu scrie niciodată o verosimilitate; se judecă după ce reproduc corect eșantioanele lui."""))
    P.block(T("Training a GAN: alternate steps and the non-saturating loss", "Antrenarea unui GAN: pași alternativi și pierderea nesaturată"), text=T(
        f"""Each step first updates the discriminator on a batch of 256 real and 256 fake days, then the generator on fresh noise. The generator minimises $-\\log D(G(\\mathbf z))$ instead of $\\log(1-D(G(\\mathbf z)))$, whose gradient vanishes when the discriminator wins early. Our GAN learns the standardised daily log returns of the S&P 500 from {v('gan.train_first')} to the end of 2019, {v('gan.n_train', ',')} days; the generator has {v('gan.params_g', ',')} and the discriminator {v('gan.params_d', ',')} parameters, trained for {v('gan.steps', ',')} steps with 3 seeds.""",
        f"""La fiecare pas se actualizează întîi discriminatorul, pe un lot de 256 de zile reale și 256 false, apoi generatorul, pe zgomot nou. Generatorul minimizează $-\\log D(G(\\mathbf z))$ în loc de $\\log(1-D(G(\\mathbf z)))$, al cărui gradient dispare cînd discriminatorul cîștigă devreme. GAN-ul nostru învață randamentele logaritmice zilnice standardizate ale indicelui S&P 500 din {v('gan.train_first')} pînă la sfîrșitul lui 2019, {v('gan.n_train', ',')} de zile; generatorul are {v('gan.params_g', ',')} de parametri, iar discriminatorul {v('gan.params_d', ',')}, antrenați {v('gan.steps', ',')} de pași, cu 3 semințe."""))
    P.block(T("The two losses settle near the equilibrium values", "Cele două pierderi se stabilizează lîngă valorile de echilibru"), text=T(
        """The discriminator loss hovers around $2\\log 2$ and the generator loss around $\\log 2$, the values that correspond to $D^*=1/2$. There is no proof of convergence for gradient play, and the curves do not measure sample quality: they only show that neither player has won.

@chart gan_losses
Discriminator and generator losses during training, seed 1.""",
        """Pierderea discriminatorului oscilează în jurul lui $2\\log 2$, iar a generatorului în jurul lui $\\log 2$, valorile care corespund lui $D^*=1/2$. Nu există o demonstrație a convergenței pentru jocul pe gradienți, iar curbele nu măsoară calitatea eșantioanelor: arată doar că niciun jucător nu a cîștigat.

@chart gan_losses
Pierderile discriminatorului și generatorului în timpul antrenării, sămînța 1."""))
    P.block(T("The GAN learns fat tails that the Gaussian misses", "GAN-ul învață cozile groase pe care distribuția normală nu le vede"), text=T(
        f"""The excess kurtosis of the real returns is {v('gan.kurt_real', '.2f')}; the GAN samples reach {v('gan.kurt_gan', '.2f')} (standard deviation {v('gan.kurt_gan_sd', '.2f')} over 3 seeds), against 0 for the Gaussian. The Kolmogorov–Smirnov distance to the real returns is {v('gan.ks_gan', '.3f')} for the GAN and {v('gan.ks_norm', '.3f')} for the fitted Gaussian.

@chart gan_density
Density, on a log scale, of real standardised returns, GAN samples and the Gaussian.""",
        f"""Excesul de aplatizare al randamentelor reale este {v('gan.kurt_real', '.2f')}; eșantioanele GAN ajung la {v('gan.kurt_gan', '.2f')} (abatere standard {v('gan.kurt_gan_sd', '.2f')} pe 3 semințe), față de 0 pentru normală. Distanța Kolmogorov–Smirnov față de randamentele reale este {v('gan.ks_gan', '.3f')} pentru GAN și {v('gan.ks_norm', '.3f')} pentru normala estimată.

@chart gan_density
Densitatea, pe scară logaritmică, a randamentelor reale standardizate, a eșantioanelor GAN și a normalei."""))
    P.block(T("A risk check: 1 % Value-at-Risk on the years after training", "Un test de risc: valoarea la risc de 1 % în anii de după antrenare"),
            frame=T("A risk check: 1", "Un test de risc: valoarea la risc de 1"), text=T(
        f"""The 1 % quantile of daily returns fitted on 2005–2019 is {v('gan.var_real_pct', '.2f')} % by historical simulation, {v('gan.var_gan_pct', '.2f')} % from the GAN samples and {v('gan.var_norm_pct', '.2f')} % for the Gaussian. On the {v('gan.n_test', ',')} days from {v('gan.test_first')} to {v('gan.test_last')}, a correct 1 % VaR is exceeded on about {v('gan.n_viol_expected')} days. The exceedance rates are {v('gan.viol_hs_pct', '.2f')} % (historical), {v('gan.viol_gan_pct', '.2f')} % (GAN) and {v('gan.viol_norm_pct', '.2f')} % (Gaussian). The expected shortfall (ES), the mean loss beyond the VaR, depends on the same tail. These are unconditional quantiles: none of the three reacts to volatility.

@practice a generator is only as good as the risk number it reproduces: backtest it like any VaR model.""",
        f"""Cuantila de 1 % a randamentelor zilnice estimată pe 2005–2019 este {v('gan.var_real_pct', '.2f')} % prin simulare istorică, {v('gan.var_gan_pct', '.2f')} % din eșantioanele GAN și {v('gan.var_norm_pct', '.2f')} % pentru normală. Pe cele {v('gan.n_test', ',')} de zile dintre {v('gan.test_first')} și {v('gan.test_last')}, o valoare VaR corectă de 1 % este depășită în circa {v('gan.n_viol_expected')} zile. Ratele depășirilor sînt {v('gan.viol_hs_pct', '.2f')} % (istorică), {v('gan.viol_gan_pct', '.2f')} % (GAN) și {v('gan.viol_norm_pct', '.2f')} % (normală). Pierderea așteptată în coadă (ES), media pierderilor dincolo de VaR, depinde de aceeași coadă. Acestea sînt cuantile necondiționate: niciuna dintre cele trei metode nu reacționează la volatilitate.

@practice un generator este atît de bun cît măsura de risc pe care o reproduce: testați-l retrospectiv ca pe orice model VaR."""))
    P.block(T("A GAN on single days cannot learn volatility clustering", "Un GAN pe zile izolate nu poate învăța gruparea volatilității"), text=T(
        f"""The autocorrelation of absolute real returns is {v('gan.acf1_real', '.2f')} at lag 1 and still {v('gan.acf20_real', '.2f')} at lag 20: calm and turbulent periods cluster. The GAN draws days independently, so its autocorrelation is {v('gan.acf1_gan', '.2f')}: the right marginal distribution with the wrong dynamics. Sequence generators, such as TimeGAN or Quant GANs, generate whole paths for this reason.

@chart gan_acf
Autocorrelation of absolute returns, lags 1 to 20, real returns and GAN samples.""",
        f"""Autocorelația randamentelor reale în valoare absolută este {v('gan.acf1_real', '.2f')} la decalajul 1 și încă {v('gan.acf20_real', '.2f')} la decalajul 20: perioadele calme și cele agitate se grupează. GAN-ul extrage zilele independent, deci autocorelația lui este {v('gan.acf1_gan', '.2f')}: distribuția marginală corectă, cu dinamica greșită. De aceea generatoarele de secvențe, ca TimeGAN sau Quant GANs, generează traiectorii întregi.

@chart gan_acf
Autocorelația randamentelor în valoare absolută, decalajele 1–20, randamente reale și eșantioane GAN."""))
    P.block(T("Mode collapse and the Wasserstein GAN", "Colapsul modurilor și GAN-ul Wasserstein"), text=T(
        """A generator can win by producing only a few convincing samples, for example only calm days and never a crash: mode collapse. The Wasserstein GAN (WGAN) replaces the Jensen–Shannon divergence by the Wasserstein distance $W_1(p_{data},p_G)=\\sup_{\\|f\\|_L\\le1}\\mathbb E_{p_{data}}[f]-\\mathbb E_{p_G}[f]$, computed by a 1-Lipschitz critic, which gives useful gradients even when the two distributions do not overlap.

@practice a stress-test generator that has collapsed onto calm days is worse than no generator.""",
        """Un generator poate cîștiga producînd doar cîteva eșantioane convingătoare, de exemplu numai zile calme și niciodată o prăbușire: colapsul modurilor. GAN-ul Wasserstein (WGAN) înlocuiește divergența Jensen–Shannon cu distanța Wasserstein $W_1(p_{data},p_G)=\\sup_{\\|f\\|_L\\le1}\\mathbb E_{p_{data}}[f]-\\mathbb E_{p_G}[f]$, calculată de o rețea critic 1-Lipschitz, care dă gradienți utili chiar cînd cele două distribuții nu se suprapun.

@practice un generator pentru teste de stres care a colapsat pe zilele calme este mai rău decît lipsa unui generator."""))
    P.add("## @end\n\n" + T("A GAN reproduces the fat tails of returns and a usable 1 % VaR, but not volatility clustering when it is trained on single days.",
                             "Un GAN reproduce cozile groase ale randamentelor și o valoare VaR de 1 % utilizabilă, dar nu și gruparea volatilității cînd este antrenat pe zile izolate.") + "\n")

    # ------------------------------------------------------------------ 5 diffusion
    P.add(T("# Diffusion models\n\nA diffusion model learns to undo, step by step, a process that turns data into noise.",
            "# Modele de difuzie\n\nUn model de difuzie învață să inverseze, pas cu pas, un proces care transformă datele în zgomot."))
    P.block(T("Diffusion models: forward noising and reverse denoising", "Modelele de difuzie: adăugarea și eliminarea treptată a zgomotului"), text=T(
        f"""The forward process adds a little Gaussian noise at each of $T$ = {v('yc.T')} steps, $q(\\mathbf x_t\\mid\\mathbf x_{{t-1}})=\\mathcal N(\\sqrt{{1-\\beta_t}}\\,\\mathbf x_{{t-1}},\\beta_tI)$, with $\\beta_t$ rising linearly from $10^{{-4}}$ to 0.02. Any step can be reached in one draw,

$$ \\mathbf x_t=\\sqrt{{\\bar\\alpha_t}}\\,\\mathbf x_0+\\sqrt{{1-\\bar\\alpha_t}}\\,\\boldsymbol\\varepsilon,\\qquad \\bar\\alpha_t=\\prod_{{s=1}}^t(1-\\beta_s), $$ {{#eq:forward}}

and at the last step $\\mathbf x_T$ is almost standard normal. The forward process has no parameters: only the reverse is learnt.""",
        f"""Procesul înainte adaugă puțin zgomot gaussian la fiecare dintre cei $T$ = {v('yc.T')} de pași, $q(\\mathbf x_t\\mid\\mathbf x_{{t-1}})=\\mathcal N(\\sqrt{{1-\\beta_t}}\\,\\mathbf x_{{t-1}},\\beta_tI)$, cu $\\beta_t$ crescînd liniar de la $10^{{-4}}$ la 0,02. Orice pas se obține dintr-o singură extragere,

$$ \\mathbf x_t=\\sqrt{{\\bar\\alpha_t}}\\,\\mathbf x_0+\\sqrt{{1-\\bar\\alpha_t}}\\,\\boldsymbol\\varepsilon,\\qquad \\bar\\alpha_t=\\prod_{{s=1}}^t(1-\\beta_s), $$ {{#eq:forward}}

iar la ultimul pas $\\mathbf x_T$ este aproape normal standard. Procesul înainte nu are parametri: se învață numai procesul invers."""))
    P.block(T("The forward process on a real yield curve", "Procesul înainte pe o curbă reală a randamentelor"), text=T(
        f"""The chart applies @eq:forward to the euro-area AAA curve of {v('yc.forward_date')}, 11 maturities from 3 months to 30 years. By step 199 the shape is gone and only noise remains; the network must learn to walk back, one small step at a time.

@chart diffusion_forward
The curve at noise steps 0, 20, 60, 120 and 199 (one draw of the noise).""",
        f"""Graficul aplică @eq:forward curbei AAA din zona euro din {v('yc.forward_date')}, cu 11 scadențe de la 3 luni la 30 de ani. La pasul 199 forma a dispărut și a rămas doar zgomot; rețeaua trebuie să învețe drumul înapoi, cîte un pas mic.

@chart diffusion_forward
Curba la pașii de zgomot 0, 20, 60, 120 și 199 (o singură extragere a zgomotului)."""))
    P.block(T("Learning to denoise: predict the noise that was added", "Învățarea eliminării zgomotului: prezicem zgomotul adăugat"), text=T(
        f"""A network $\\boldsymbol\\varepsilon_\\theta(\\mathbf x_t,t)$ sees a noisy curve and the step, and predicts the noise:

$$ \\mathcal L(\\theta)=\\mathbb E_{{t,\\mathbf x_0,\\boldsymbol\\varepsilon}}\\big\\|\\boldsymbol\\varepsilon-\\boldsymbol\\varepsilon_\\theta(\\sqrt{{\\bar\\alpha_t}}\\mathbf x_0+\\sqrt{{1-\\bar\\alpha_t}}\\boldsymbol\\varepsilon,t)\\big\\|^2, $$ {{#eq:ddpm}}

a simplified, reweighted ELBO. Generation starts from pure noise and applies $\\mathbf x_{{t-1}}=\\big(\\mathbf x_t-\\beta_t\\boldsymbol\\varepsilon_\\theta/\\sqrt{{1-\\bar\\alpha_t}}\\big)/\\sqrt{{\\alpha_t}}+\\sqrt{{\\beta_t}}\\mathbf u$ down to $t=0$. Our denoiser is an MLP with three hidden layers of 256 units and a sinusoidal embedding of $t$, {v('yc.params', ',')} parameters, trained for {v('yc.steps', ',')} steps on the {v('yc.n_days', ',')} daily curves of the European Central Bank from {v('yc.first')} to {v('yc.last')}.""",
        f"""O rețea $\\boldsymbol\\varepsilon_\\theta(\\mathbf x_t,t)$ vede o curbă cu zgomot și pasul și prezice zgomotul:

$$ \\mathcal L(\\theta)=\\mathbb E_{{t,\\mathbf x_0,\\boldsymbol\\varepsilon}}\\big\\|\\boldsymbol\\varepsilon-\\boldsymbol\\varepsilon_\\theta(\\sqrt{{\\bar\\alpha_t}}\\mathbf x_0+\\sqrt{{1-\\bar\\alpha_t}}\\boldsymbol\\varepsilon,t)\\big\\|^2, $$ {{#eq:ddpm}}

un ELBO simplificat și reponderat. Generarea pornește de la zgomot pur și aplică $\\mathbf x_{{t-1}}=\\big(\\mathbf x_t-\\beta_t\\boldsymbol\\varepsilon_\\theta/\\sqrt{{1-\\bar\\alpha_t}}\\big)/\\sqrt{{\\alpha_t}}+\\sqrt{{\\beta_t}}\\mathbf u$ pînă la $t=0$. Rețeaua noastră este un MLP cu trei straturi ascunse de 256 de unități și o reprezentare sinusoidală a lui $t$, cu {v('yc.params', ',')} de parametri, antrenată {v('yc.steps', ',')} de pași pe cele {v('yc.n_days', ',')} de curbe zilnice ale Băncii Centrale Europene, din {v('yc.first')} pînă în {v('yc.last')}."""))
    P.block(T("Diffusion reproduces the two regimes of euro rates; a Gaussian cannot", "Difuzia reproduce cele două regimuri ale dobînzilor euro; distribuția normală nu poate"), text=T(
        f"""The real 10-year yield ranges from {v('yc.y10_min', '.2f')} % to {v('yc.y10_max', '.2f')} % and is negative on {v('yc.pct_neg10_real', '.1f')} % of the days: there is a low-rate and a normal-rate regime. The Wasserstein distance between the generated and the real 10-year yield is {v('yc.ddpm.w_y10', '.3f')} percentage points for the diffusion model, {v('yc.vae.w_y10', '.3f')} for a two-factor VAE and {v('yc.gauss.w_y10', '.3f')} for a multivariate Gaussian.

@chart yc_density
Density of the 10-year yield, real curves and 5,000 curves from each generator.""",
        f"""Randamentul real la 10 ani variază între {v('yc.y10_min', '.2f')} % și {v('yc.y10_max', '.2f')} % și este negativ în {v('yc.pct_neg10_real', '.1f')} % dintre zile: există un regim de dobînzi scăzute și unul de dobînzi normale. Distanța Wasserstein dintre randamentul generat și cel real la 10 ani este {v('yc.ddpm.w_y10', '.3f')} puncte procentuale pentru modelul de difuzie, {v('yc.vae.w_y10', '.3f')} pentru un VAE cu doi factori și {v('yc.gauss.w_y10', '.3f')} pentru o normală multivariată.

@chart yc_density
Densitatea randamentului la 10 ani, curbele reale și cîte 5 000 de curbe din fiecare generator."""))
    P.block(T("Level and slope move together in a curved way that diffusion keeps", "Nivelul și panta se mișcă împreună, într-un mod curb, pe care difuzia îl păstrează"), text=T(
        f"""A curve is inverted when the 10-year yield is below the 3-month yield. This happened on {v('yc.pct_inverted_real', '.1f')} % of the real days; {v('yc.ddpm.pct_inverted', '.1f')} % of the diffusion samples and {v('yc.gauss.pct_inverted', '.1f')} % of the Gaussian samples are inverted. The Wasserstein distance of the slope is {v('yc.ddpm.w_slope', '.3f')} for the diffusion model, {v('yc.vae.w_slope', '.3f')} for the VAE and {v('yc.gauss.w_slope', '.3f')} for the Gaussian.

@chart yc_scatter
Level (10-year yield) against slope (10 years minus 3 months): real curves, diffusion samples and Gaussian samples.""",
        f"""O curbă este inversată cînd randamentul la 10 ani este sub cel la 3 luni. Acest lucru s-a întîmplat în {v('yc.pct_inverted_real', '.1f')} % dintre zilele reale; {v('yc.ddpm.pct_inverted', '.1f')} % dintre eșantioanele difuziei și {v('yc.gauss.pct_inverted', '.1f')} % dintre cele normale sînt inversate. Distanța Wasserstein a pantei este {v('yc.ddpm.w_slope', '.3f')} pentru modelul de difuzie, {v('yc.vae.w_slope', '.3f')} pentru VAE și {v('yc.gauss.w_slope', '.3f')} pentru normală.

@chart yc_scatter
Nivelul (randamentul la 10 ani) față de pantă (10 ani minus 3 luni): curbe reale, eșantioane ale difuziei și eșantioane normale."""))
    P.block(T("A two-factor VAE of the curve rediscovers level and slope", "Un VAE cu doi factori ai curbei redescoperă nivelul și panta"), text=T(
        f"""The VAE used as a benchmark compresses each curve into two latent numbers. Their correlations with the level (mean of the 11 yields) and the slope reach {v('yc.vae_corr.max_level', '.2f')} and {v('yc.vae_corr.max_slope', '.2f')} in absolute value: without being told, the latent path tracks the low-rate era of 2014–2021 and the tightening of 2022.

@chart yc_latent_time
Latent means of the two-factor VAE over time.""",
        f"""VAE-ul folosit ca model de referință comprimă fiecare curbă în două numere latente. Corelațiile lor cu nivelul (media celor 11 randamente) și cu panta ajung la {v('yc.vae_corr.max_level', '.2f')} și {v('yc.vae_corr.max_slope', '.2f')} în valoare absolută: fără să i se spună, traiectoria latentă urmărește perioada de dobînzi scăzute 2014–2021 și înăsprirea din 2022.

@chart yc_latent_time
Mediile latente ale VAE-ului cu doi factori, în timp."""))
    P.add("## @end\n\n" + T("Diffusion learns to undo noise; on euro yield curves it keeps both rate regimes and the inversions that a Gaussian misses.",
                             "Difuzia învață să elimine zgomotul; pe curbele euro păstrează ambele regimuri de dobîndă și inversările pe care distribuția normală nu le vede.") + "\n")

    # ------------------------------------------------------------------ 6 practice
    P.add(T("# Generative models in practice\n\nSynthetic data are useful only after they pass the same checks as real data.",
            "# Modelele generative în practică\n\nDatele sintetice sînt utile numai după ce trec aceleași verificări ca datele reale."))
    P.block(T("How to judge synthetic financial data", "Cum judecăm datele financiare sintetice"), text=T(
        """Four questions. Fidelity: do the marginals, the tails and the dependence across assets and over time match? Diversity: are extreme days and regimes present in the right proportions, with no mode collapse? Utility: does a model trained on synthetic data and tested on real data (TSTR) work? Privacy: is any sample too close to a real record? On our data the GAN gets the tails right and the clustering wrong; the diffusion model gets the regimes and the inversions right, the Gaussian does not.

@practice never use synthetic data for a decision before it passes the same backtests as the model it feeds.""",
        """Patru întrebări. Fidelitatea: se potrivesc distribuțiile marginale, cozile și dependența între active și în timp? Diversitatea: apar zilele extreme și regimurile în proporțiile corecte, fără colaps al modurilor? Utilitatea: funcționează un model antrenat pe date sintetice și testat pe date reale (TSTR)? Confidențialitatea: este vreun eșantion prea aproape de o înregistrare reală? Pe datele noastre, GAN-ul reproduce corect cozile și greșește gruparea volatilității; modelul de difuzie reproduce regimurile și inversările, normala nu.

@practice nu folosiți date sintetice într-o decizie înainte ca ele să treacă aceleași teste retrospective ca modelul pe care îl alimentează."""))
    P.block(T("Choosing a generative model", "Alegerea unui model generativ"), text=T(
        f"""Autoencoders are the tool to monitor (an anomaly score), VAEs to compress and explore (smooth latent factors), diffusion models to simulate faithfully at the cost of {v('yc.T')} network passes per sample, and GANs when sampling must be fast and the training can be watched closely.""",
        f"""Autoencoderele sînt instrumentul de monitorizare (un scor de anomalie), VAE pentru comprimare și explorare (factori latenți netezi), modelele de difuzie pentru simulări fidele, cu prețul a {v('yc.T')} de treceri prin rețea pentru fiecare eșantion, iar GAN cînd generarea trebuie să fie rapidă și antrenarea poate fi urmărită îndeaproape."""))
    P.add("## @end\n\n" + T("Pick the family by the use: monitoring, compression, faithful simulation or fast sampling; then backtest the output.",
                             "Alegeți familia după utilizare: monitorizare, comprimare, simulare fidelă sau generare rapidă; apoi testați retrospectiv rezultatul.") + "\n")
    P.write()


